// ===== 1. Mensaje que llegó =====
const msg = $('Telegram Trigger').first().json.message || {};
const chatId = String(msg.chat?.id ?? '');
const texto = String(msg.text || '').trim();

// ===== 2. Datos de Google Sheets (se ignoran los items vacíos) =====
const filas = (nodo) => $(nodo).all().map(i => i.json).filter(r => Object.keys(r).length > 0);
const sesiones = filas('Leer SESSIONS');
const estudiantes = filas('Leer ESTUDIANTES');
const tutores = filas('Leer TUTORES');
const dispo = filas('Leer DISPONIBILIDAD');
const tutorias = filas('Leer TUTORIAS');

// ===== 3. Utilidades =====
const DIAS = ['Domingo', 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado'];
const ACTIVAS = ['Solicitada', 'Asignada', 'Confirmada'];
const norm = s => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const hoy = new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10); // Bogotá, UTC-5
const MENU = 'Menú principal\n1. Solicitar tutoría\n2. Mis tutorías\n3. Cancelar tutoría\n\nEscribe 0 en cualquier momento para volver aquí.';
const materiasDe = t => String(t.especialidad_materias || '').split(/[;,]/).map(m => m.trim()).filter(Boolean);
const siguienteId = (pref, lista, campo) => pref + String(lista.reduce((m, r) => Math.max(m, parseInt(String(r[campo] ?? '').replace(/\D/g, ''), 10) || 0), 0) + 1).padStart(3, '0');
const tutorPorId = id => tutores.find(t => String(t.id_tutor) === String(id));
const tutoresActivos = tutores.filter(t => norm(t.estado) === 'activo');
const materias = [...new Set(tutoresActivos.flatMap(materiasDe))].sort();
const ocupadoTutor = (idTutor, fecha, hora) => tutorias.some(t => String(t.id_tutor) === String(idTutor) && String(t.fecha) === fecha && String(t.hora) === hora && ACTIVAS.includes(t.estado));
const ocupadoEst = (fecha, hora) => tutorias.some(t => String(t.id_estudiante) === chatId && String(t.fecha) === fecha && String(t.hora) === hora && ACTIVAS.includes(t.estado));
const linea = t => `${t.id_tutoria} · ${t.materia} · ${t.fecha} ${t.hora} · ${tutorPorId(t.id_tutor)?.nombre ?? 'Sin tutor'} · ${t.estado}`;
const listaOpciones = ops => ops.map((o, i) => `${i + 1}. ${o.tutor} · ${o.hora_inicio}-${o.hora_fin}`).join('\n');

// ===== 4. Sesión actual =====
const ses = sesiones.find(s => String(s.telegram_user) === chatId);
let pantalla = ses?.pantalla_actual || 'MENU';
let paso = String(ses?.paso_actual || 'INICIO');
let datos = {};
try { datos = ses?.datos_parciales ? JSON.parse(ses.datos_parciales) : {}; } catch (e) { datos = {}; }

// ===== 5. Objeto de salida =====
const out = { chat_id: chatId, respuesta: '', nuevo_estudiante: null, nueva_tutoria: null, actualizar_tutoria: null, notificaciones: [] };
const ir = (p, s, d, r) => { pantalla = p; paso = s; datos = d; out.respuesta = r; };
const estudiante = estudiantes.find(e => String(e.id_estudiante) === chatId);
const tutorYo = tutores.find(t => t.telegram_chat_id && String(t.telegram_chat_id) === chatId);

// ===== 6. Lógica =====
if (tutorYo && texto.startsWith('/') && texto !== '/start') {
  // --- Comandos del tutor ---
  const [cmd, idArg] = texto.split(/\s+/);
  const t = tutorias.find(x => x.id_tutoria === idArg && String(x.id_tutor) === String(tutorYo.id_tutor));
  if (cmd === '/agenda') {
    const prox = tutorias.filter(x => String(x.id_tutor) === String(tutorYo.id_tutor) && String(x.fecha) >= hoy && ACTIVAS.includes(x.estado))
      .sort((a, b) => (a.fecha + a.hora).localeCompare(b.fecha + b.hora));
    out.respuesta = prox.length ? 'Tu agenda:\n' + prox.map(linea).join('\n') : 'No tienes tutorías próximas.';
  } else if ((cmd === '/confirmar' || cmd === '/finalizar') && t) {
    const estado = cmd === '/confirmar' ? 'Confirmada' : 'Finalizada';
    out.actualizar_tutoria = { id_tutoria: t.id_tutoria, estado };
    out.notificaciones.push({ chat_id: String(t.id_estudiante), texto: `Tu tutoría ${t.id_tutoria} de ${t.materia} (${t.fecha} ${t.hora}) quedó ${estado}.` });
    out.respuesta = `Listo: ${t.id_tutoria} quedó ${estado}.`;
  } else {
    out.respuesta = 'Comandos de tutor:\n/agenda\n/confirmar T001\n/finalizar T001';
  }
} else if (!estudiante) {
  // --- Registro ---
  if (pantalla === 'REGISTRO' && texto.length >= 3 && !texto.startsWith('/')) {
    out.nuevo_estudiante = { id_estudiante: chatId, nombre: texto, fecha_registro: hoy };
    ir('MENU', 'INICIO', {}, `¡Registro listo, ${texto}!\n\n${MENU}`);
  } else {
    ir('REGISTRO', 'NOMBRE', {}, 'Hola, soy TutorBot. Para registrarte escribe tu nombre completo.');
  }
} else if (['0', '/start', 'menu'].includes(norm(texto))) {
  ir('MENU', 'INICIO', {}, MENU);
} else if (pantalla === 'MENU') {
  if (texto === '1') {
    if (!materias.length) out.respuesta = 'No hay materias con tutores activos.\n\n' + MENU;
    else ir('SOLICITAR', 'MATERIA', {}, 'Elige la materia:\n' + materias.map((m, i) => `${i + 1}. ${m}`).join('\n'));
  } else if (texto === '2') {
    const mias = tutorias.filter(t => String(t.id_estudiante) === chatId)
      .sort((a, b) => (b.fecha + b.hora).localeCompare(a.fecha + a.hora)).slice(0, 10);
    out.respuesta = (mias.length ? 'Tus tutorías:\n' + mias.map(linea).join('\n') : 'Aún no tienes tutorías.') + '\n\n' + MENU;
  } else if (texto === '3') {
    const cancelables = tutorias.filter(t => String(t.id_estudiante) === chatId && ACTIVAS.includes(t.estado) && String(t.fecha) >= hoy);
    if (!cancelables.length) out.respuesta = 'No tienes tutorías para cancelar.\n\n' + MENU;
    else ir('CANCELAR', 'ELEGIR', { ids: cancelables.map(t => t.id_tutoria) }, '¿Cuál quieres cancelar?\n' + cancelables.map((t, i) => `${i + 1}. ${linea(t)}`).join('\n'));
  } else {
    out.respuesta = MENU;
  }
} else if (pantalla === 'SOLICITAR') {
  if (paso === 'MATERIA') {
    const n = parseInt(texto, 10);
    if (n >= 1 && n <= materias.length) ir('SOLICITAR', 'FECHA', { materia: materias[n - 1] }, `Materia: ${materias[n - 1]}.\nEscribe la fecha en formato YYYY-MM-DD (ej. ${hoy}).`);
    else out.respuesta = `Escribe un número del 1 al ${materias.length}.`;
  } else if (paso === 'FECHA') {
    const d = new Date(texto + 'T12:00:00Z');
    const valida = /^\d{4}-\d{2}-\d{2}$/.test(texto) && !isNaN(d) && d.toISOString().slice(0, 10) === texto;
    if (!valida) out.respuesta = 'Fecha no válida. Usa YYYY-MM-DD, por ejemplo 2026-12-01.';
    else if (texto < hoy) out.respuesta = 'Esa fecha ya pasó. Escribe una fecha de hoy en adelante.';
    else {
      const dia = DIAS[d.getUTCDay()];
      const ids = tutoresActivos.filter(t => materiasDe(t).includes(datos.materia)).map(t => String(t.id_tutor));
      const opciones = dispo
        .filter(x => ids.includes(String(x.id_tutor)) && norm(x.dia_semana) === norm(dia) && norm(x.estado) === 'libre')
        .filter(x => !ocupadoTutor(x.id_tutor, texto, String(x.hora_inicio)) && !ocupadoEst(texto, String(x.hora_inicio)))
        .sort((a, b) => String(a.hora_inicio).localeCompare(String(b.hora_inicio)))
        .slice(0, 9)
        .map(x => ({ id_dispo: x.id_dispo, id_tutor: String(x.id_tutor), tutor: tutorPorId(x.id_tutor).nombre, hora_inicio: String(x.hora_inicio), hora_fin: String(x.hora_fin) }));
      const base = { ...datos, fecha: texto, dia };
      if (opciones.length) ir('SOLICITAR', 'ELEGIR', { ...base, opciones }, `Horarios libres el ${dia} ${texto}:\n` + listaOpciones(opciones));
      else ir('SOLICITAR', 'SIN_CUPO', base, `No hay tutores libres de ${datos.materia} el ${dia} ${texto}.\n1. Dejar la solicitud pendiente para coordinación\n2. Probar otra fecha`);
    }
  } else if (paso === 'ELEGIR') {
    const ops = datos.opciones || [];
    const o = ops[parseInt(texto, 10) - 1];
    if (!o) out.respuesta = `Escribe un número del 1 al ${ops.length}.`;
    else ir('SOLICITAR', 'CONFIRMAR', { ...datos, elegida: o }, `Confirma tu tutoría:\n${datos.materia} · ${datos.dia} ${datos.fecha} · ${o.hora_inicio}-${o.hora_fin} · Tutor: ${o.tutor}\n\n1. Confirmar\n2. Elegir otro horario`);
  } else if (paso === 'CONFIRMAR') {
    const o = datos.elegida;
    if (texto === '1') {
      if (ocupadoTutor(o.id_tutor, datos.fecha, o.hora_inicio)) {
        ir('SOLICITAR', 'FECHA', { materia: datos.materia }, 'Ese horario se acaba de ocupar. Escribe la fecha otra vez para ver lo que queda.');
      } else {
        const id = siguienteId('T', tutorias, 'id_tutoria');
        out.nueva_tutoria = { id_tutoria: id, id_estudiante: chatId, id_tutor: o.id_tutor, materia: datos.materia, fecha: datos.fecha, hora: o.hora_inicio, estado: 'Asignada', id_dispo: o.id_dispo, creado_en: new Date().toISOString() };
        const tutor = tutorPorId(o.id_tutor);
        if (tutor?.telegram_chat_id) out.notificaciones.push({ chat_id: String(tutor.telegram_chat_id), texto: `Nueva tutoría ${id}: ${datos.materia} con ${estudiante.nombre}, ${datos.dia} ${datos.fecha} a las ${o.hora_inicio}.\nConfírmala con /confirmar ${id}` });
        ir('MENU', 'INICIO', {}, `Tutoría ${id} asignada con ${o.tutor} el ${datos.fecha} a las ${o.hora_inicio}. Te avisaré cuando el tutor la confirme.\n\n${MENU}`);
      }
    } else if (texto === '2') {
      ir('SOLICITAR', 'ELEGIR', datos, 'Elige otro horario:\n' + listaOpciones(datos.opciones || []));
    } else out.respuesta = 'Escribe 1 para confirmar o 2 para elegir otro horario.';
  } else if (paso === 'SIN_CUPO') {
    if (texto === '1') {
      const id = siguienteId('T', tutorias, 'id_tutoria');
      out.nueva_tutoria = { id_tutoria: id, id_estudiante: chatId, id_tutor: '', materia: datos.materia, fecha: datos.fecha, hora: '', estado: 'Solicitada', id_dispo: '', creado_en: new Date().toISOString() };
      ir('MENU', 'INICIO', {}, `Solicitud ${id} registrada como pendiente. Coordinación te asignará un tutor.\n\n${MENU}`);
    } else if (texto === '2') ir('SOLICITAR', 'FECHA', { materia: datos.materia }, 'Escribe otra fecha (YYYY-MM-DD).');
    else out.respuesta = 'Escribe 1 o 2.';
  }
} else if (pantalla === 'CANCELAR') {
  const ids = datos.ids || [];
  const t = tutorias.find(x => x.id_tutoria === ids[parseInt(texto, 10) - 1]);
  if (!t) out.respuesta = `Escribe un número del 1 al ${ids.length}.`;
  else {
    out.actualizar_tutoria = { id_tutoria: t.id_tutoria, estado: 'Cancelada' };
    const tutor = tutorPorId(t.id_tutor);
    if (tutor?.telegram_chat_id) out.notificaciones.push({ chat_id: String(tutor.telegram_chat_id), texto: `El estudiante canceló la tutoría ${t.id_tutoria} (${t.materia}, ${t.fecha} ${t.hora}).` });
    ir('MENU', 'INICIO', {}, `Tutoría ${t.id_tutoria} cancelada.\n\n${MENU}`);
  }
}

// Si ningún caso respondió (sesión dañada o paso desconocido), vuelve al menú
if (!out.respuesta) ir('MENU', 'INICIO', {}, MENU);

out.sesion = { telegram_user: chatId, pantalla_actual: pantalla, paso_actual: paso, datos_parciales: JSON.stringify(datos) };
return [{ json: out }];
